import json

class StakeholderInterview:
    def __init__(self, participant_type, requirements):
        self.participant_type = participant_type
        self.requirements = requirements

    def to_dict(self):
        return {"participant_type": self.participant_type, "requirements": self.requirements}

def finalize_interviews(remaining_participants, existing_requirements):
    interviews = []
    for participant in remaining_participants:
        requirements = {
            "functional": [],
            "non_functional": []
        }
        # Simulate gathering requirements from participant
        requirements["functional"].append(f"{participant}_functional_req")
        requirements["non_functional"].append(f"{participant}_non_functional_req")
        interview = StakeholderInterview(participant, requirements)
        interviews.append(interview.to_dict())
        existing_requirements.update({participant: requirements})
    return interviews, existing_requirements

# Example usage
remaining_participants = ["teacher_3", "student_3", "administrator_2"]
existing_requirements = {}
interviews, updated_requirements = finalize_interviews(remaining_participants, existing_requirements)
print(json.dumps(updated_requirements, indent=4))

