import json

def prioritize_requirements(requirements):
    prioritized = {
        "must_have": [],
        "should_have": [],
        "nice_to_have": []
    }
    for participant, reqs in requirements.items():
        for func_req in reqs["functional"]:
            prioritized["must_have"].append(func_req)
        for non_func_req in reqs["non_functional"]:
            prioritized["should_have"].append(non_func_req)
    return prioritized

# Example usage with updated_requirements from stakeholder_interviews.py
prioritized = prioritize_requirements(updated_requirements)
print(json.dumps(prioritized, indent=4))
